krpano.action:
(function () {
  var id = new URLSearchParams(window.location.search).get("id");
  if (!id || !/^[A-Za-z0-9_-]{1,100}$/.test(id)) {
    console.error("Invalid HTML id:", id);
    return;
  }
  var htmlUrl = "https://ryanedua.github.io/verification-demo/html/" +
    encodeURIComponent(id) + ".html";
  fetch(htmlUrl)
    .then(function (response) {
      if (!response.ok) throw new Error("HTML request failed: " + response.status);
      return response.text();
    })
    .then(function (html) {
      document.open();
      document.write(html);
      document.close();
    })
    .catch(function (error) { console.error("HTML viewer:", error); });
}());
